from taf.sbts.oam.coam.admin import admin

from .bts import Bts


class BtsClassical(Bts):
    def __init__(self, config, alias):
        """
        :param config: configuration object of BTS towards which communication will be directed;
                       should contain all data required to connect to given BTS;
                       if None will be provided then default connection data will be used
        :type config: taf.config.testline.gnb.gnb.gNB or None
        :param alias: connection alias which will be used during creation of BTS connection
        :type alias: str
        """
        super(BtsClassical, self).__init__(alias)
        self._api = admin()
        self._ip = config.cu.oam_http_connection_details.addr if config else '192.168.255.129'
        self._port = config.cu.oam_http_connection_details.port if config else 443
        self._username = config.cu.oam_http_connection_details.username if config else 'Nemuadmin'
        self._password = config.cu.oam_http_connection_details.password if config else 'nemuuser'

    def _connect_to(self, log_dir):
        self._logger.info(self._CONNECTION_LOG_MSG.format(
            'gNB classical', self._ip, self._port, self._username, self._password))

        self._api.connect_to(bts_host=self._ip,
                             bts_port=self._port,
                             username=self._username,
                             password=self._password,
                             name=self._alias,
                             admin_api_log_dir=log_dir)

        self._logger.info("Connected to BTS")

    def _get_statuses(self, dist_name, timeout):
        return self._api.get_parameters(dist_name=dist_name, connection=self._alias, timeout=timeout)

    def _disconnect(self):
        self._logger.info(self._DISCONNECTION_LOG_MSG.format(
            'gNB classical', self._ip, self._port, self._username, self._password))
        self._api.teardown(connection=self._alias)
        self._logger.info("Disconnected from BTS")
